//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns `true` only for [`RetryError::Transient`] failures, which the
    /// retry policy may retry. Permanent failures must not be retried.
    pub fn is_transient(&self) -> bool {
        matches!(self, RetryError::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Upper bound for any retry delay, in milliseconds. Exponential delay
    /// growth saturates at this value.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Creates a bounded exponential retry policy.
    ///
    /// The first retry waits `base_delay_ms`; each later retry doubles the
    /// delay, capped at `max_delay_ms`.
    pub fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    /// Delay before the retry that follows `retry_index` failed attempts
    /// (0-based): retry 0 waits `base_delay_ms`, retry 1 waits
    /// `2 * base_delay_ms`, and so on, always capped at `max_delay_ms`.
    ///
    /// Safe for arbitrarily large retry indices: once the exponent exceeds
    /// the width of `u64`, the delay saturates at `max_delay_ms` instead of
    /// overflowing.
    pub fn delay_before_retry(&self, retry_index: u32) -> u64 {
        let multiplier = 1u64.checked_shl(retry_index).unwrap_or(u64::MAX);
        self.base_delay_ms
            .saturating_mul(multiplier)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn first_retry_uses_base_delay() {
        let config = RetryConfig::new(5, 100, 10_000);
        assert_eq!(config.delay_before_retry(0), 100);
    }

    #[test]
    fn delay_doubles_each_retry() {
        let config = RetryConfig::new(5, 100, 10_000);
        assert_eq!(config.delay_before_retry(1), 200);
        assert_eq!(config.delay_before_retry(2), 400);
        assert_eq!(config.delay_before_retry(3), 800);
    }

    #[test]
    fn delay_saturates_at_max_delay_ms() {
        let config = RetryConfig::new(5, 100, 1_000);
        assert_eq!(config.delay_before_retry(3), 800);
        assert_eq!(config.delay_before_retry(4), 1_000);
        assert_eq!(config.delay_before_retry(5), 1_000);
        assert_eq!(config.delay_before_retry(100), 1_000);
    }

    #[test]
    fn huge_exponents_do_not_overflow() {
        // retry_index beyond u64's bit width must saturate, not overflow.
        let config = RetryConfig::new(u32::MAX, 1, u64::MAX);
        assert_eq!(config.delay_before_retry(u32::MAX), u64::MAX);

        let config = RetryConfig::new(u32::MAX, 1_000, 5_000);
        assert_eq!(config.delay_before_retry(u32::MAX), 5_000);
    }

    #[test]
    fn zero_base_delay_stays_zero() {
        let config = RetryConfig::new(3, 0, 1_000);
        assert_eq!(config.delay_before_retry(0), 0);
        assert_eq!(config.delay_before_retry(7), 0);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

