pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
///
/// * `max_attempts` includes the first call.
/// * Only [`RetryError::Transient`] failures are retried; a
///   [`RetryError::Permanent`] failure returns immediately.
/// * The first retry waits `base_delay_ms`; each later retry doubles the
///   delay, capped at `max_delay_ms`.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut last_error = None;
    for attempt in 0..config.max_attempts {
        match job() {
            Ok(()) => return Ok(()),
            Err(err) => {
                if !err.is_transient() {
                    return Err(err);
                }
                last_error = Some(err);
                // Do not sleep after the final allowed attempt.
                if attempt + 1 < config.max_attempts {
                    sleeper.sleep_ms(config.delay_before_retry(attempt));
                }
            }
        }
    }
    // Only reachable when max_attempts is 0, which the policy forbids.
    Err(last_error.unwrap_or_else(|| {
        RetryError::Permanent("max_attempts must be at least 1".to_string())
    }))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn succeeds_on_first_attempt_without_sleeping() {
        let config = RetryConfig::new(3, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config, &mut sleeper, || Ok(()));
        assert_eq!(result, Ok(()));
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn transient_failure_is_retried_with_exponential_delay() {
        let config = RetryConfig::new(4, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(RetryError::Transient("flaky".to_string()))
            } else {
                Ok(())
            }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn permanent_failure_returns_immediately() {
        let config = RetryConfig::new(4, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("bad input".to_string()))
        });
        assert_eq!(
            result,
            Err(RetryError::Permanent("bad input".to_string()))
        );
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let config = RetryConfig::new(3, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("flaky".to_string()))
        });
        assert_eq!(
            result,
            Err(RetryError::Transient("flaky".to_string()))
        );
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn single_attempt_never_sleeps() {
        let config = RetryConfig::new(1, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("flaky".to_string()))
        });
        assert!(result.is_err());
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn delays_saturate_at_max_delay_ms() {
        let config = RetryConfig::new(6, 10, 25);
        let mut sleeper = FakeSleeper::default();
        let _ = run_job(&config, &mut sleeper, || {
            Err(RetryError::Transient("flaky".to_string()))
        });
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25, 25]);
    }
}

# jobrunner

Small job runner with a pluggable retry policy.

## Retry policy

`run_job` executes a job with a configurable bounded exponential retry
policy:

- **Transient errors are retried; permanent errors return immediately.**
  Only `RetryError::Transient` failures are retried. A
  `RetryError::Permanent` failure stops the run at once.
- **`max_attempts` includes the first call.** With `max_attempts = 3`, the
  job may run up to three times before the last error is returned.
- **Delay growth is exponential and saturates.** The first retry waits
  `base_delay_ms`; each later retry doubles the delay, capped at
  `max_delay_ms`. The cap is applied with saturating arithmetic, so
  arbitrarily large attempt counts never overflow and simply wait
  `max_delay_ms` each time.

## Configuration

```rust
use jobrunner::{run_job, RetryConfig, RetryError};

let config = RetryConfig::new(
    /* max_attempts */ 5,
    /* base_delay_ms */ 100,
    /* max_delay_ms  */ 2_000,
);
```

The first retry waits 100 ms, the second 200 ms, the third 400 ms, the
fourth 800 ms, and any later retry saturates at 2 000 ms.

## Example

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig::new(5, 100, 2_000);
let mut sleeper = FakeSleeper::default(); // records delays instead of waiting
let mut calls = 0;

let result = run_job(&config, &mut sleeper, || {
    calls += 1;
    if calls < 3 {
        Err(RetryError::Transient("not ready yet".to_string()))
    } else {
        Ok(())
    }
});

assert_eq!(result, Ok(()));
assert_eq!(calls, 3);
assert_eq!(sleeper.sleeps, vec![100, 200]);
```

In production, pass a real sleeper (for example one that calls
`std::thread::sleep`) instead of `FakeSleeper`; tests use `FakeSleeper` so
they never actually wait.

//! Integration coverage for the public retry policy contract.

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn succeeds_after_transient_failures() {
    let config = RetryConfig::new(5, 10, 100);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 3 {
            Err(RetryError::Transient("not yet".to_string()))
        } else {
            Ok(())
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn permanent_error_returns_immediately_without_retries() {
    let config = RetryConfig::new(10, 10, 100);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("bad input".to_string()))
    });
    assert_eq!(result, Err(RetryError::Permanent("bad input".to_string())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn max_attempts_includes_the_first_call() {
    let config = RetryConfig::new(3, 10, 100);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("flaky".to_string()))
    });
    assert_eq!(result, Err(RetryError::Transient("flaky".to_string())));
    assert_eq!(calls, 3);
    // Two retries follow the first call, so two sleeps with exponential delays.
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn delays_saturate_at_max_delay_ms() {
    let config = RetryConfig::new(10, 10, 25);
    let mut sleeper = FakeSleeper::default();
    let result = run_job(&config, &mut sleeper, || {
        Err(RetryError::Transient("flaky".to_string()))
    });
    assert_eq!(result, Err(RetryError::Transient("flaky".to_string())));
    // 10 attempts -> 9 sleeps: 10, 20, then 25 forever (40+ capped).
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25, 25, 25, 25, 25, 25]);
}

#[test]
fn huge_attempt_budget_saturates_without_overflow() {
    let config = RetryConfig::new(u32::MAX, 1, 1_000);
    let mut sleeper = FakeSleeper::default();
    // The run would need an unbounded job, so only the delay computation is
    // exercised: a retry index beyond u64's bit width must saturate at
    // max_delay_ms rather than overflow.
    assert_eq!(config.delay_before_retry(u32::MAX), 1_000);
    assert_eq!(config.delay_before_retry(10_000), 1_000);
    // And the policy itself must accept the extreme budget without panicking
    // when the job succeeds immediately.
    let result = run_job(&config, &mut sleeper, || Ok(()));
    assert_eq!(result, Ok(()));
}
